1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
78	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
79	const FULL_REIMBURSEMENT_RATE = 1;
80	const CAP_MULTIPLIER = 2;
81	
82	const CURSE_SURCHARGE_RATE = 0.5;
83	const HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
84	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
85	const LOYALTY_YEARS_THRESHOLD = 2;
86	const LOYALTY_DISCOUNT_RATE = 0.2;
87	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
88	
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	
92	// The MHPCO insures only what is on its price list.
93	const basePremiumForType = (type: string): number => {
94	  const basePremium = BASE_PREMIUMS[type];
95	  if (basePremium === undefined) {
96	    throw new Error(`the MHPCO does not insure items of type ${type}`);
97	  }
98	
99	  return basePremium;
100	};
101	
102	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
103	
104	const countByType = (items: Item[]): Map<string, number> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return counts;
110	};
111	
112	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
113	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
114	
115	const groupBasePremium = (type: string, count: number): number =>
116	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
117	
118	const policyBasePremium = (items: Item[]): number =>
119	  [...countByType(items)].reduce(
120	    (total, [type, count]) => total + groupBasePremium(type, count),
121	    0,
122	  );
123	
124	// The MHPCO rounds in its own favour, which cuts in opposite directions for
125	// the two quantities it settles: premiums up, payouts down.
126	const roundPremiumInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
127	const roundPayoutInMHPCOsFavour = (amount: number): number => Math.floor(amount);
128	
129	// Item-scoped surcharge clauses. Each applies, independently and additively,
130	// to the affected item's own base premium.
131	const ITEM_SURCHARGE_CLAUSES: {
132	  applies: (item: Item) => boolean;
133	  rate: number;
134	}[] = [
135	  {
136	    applies: (item) => item.cursed === true,
137	    rate: CURSE_SURCHARGE_RATE,
138	  },
139	  {
140	    applies: (item) =>
141	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD,
142	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
143	  },
144	];
145	
146	const itemSurcharge = (item: Item): number => {
147	  const base = itemBasePremium(item);
148	
149	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
150	    (total, clause) => total + base * clause.rate,
151	    0,
152	  );
153	};
154	
155	const itemSurcharges = (items: Item[]): number =>
156	  items.reduce((total, item) => total + itemSurcharge(item), 0);
157	
158	// Everything a policy-scoped clause may inspect.
159	type Policy = {
160	  items: Item[];
161	  customer: Customer;
162	  isFollowUpContract: boolean;
163	};
164	
165	// Policy-scoped modifier clauses. Each applies, independently and additively,
166	// to the policy base premium. A negative rate is a discount.
167	const POLICY_MODIFIER_CLAUSES: {
168	  applies: (policy: Policy) => boolean;
169	  rate: number;
170	}[] = [
171	  {
172	    applies: () => true,
173	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
174	  },
175	  {
176	    applies: (policy) =>
177	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
178	    rate: -LOYALTY_DISCOUNT_RATE,
179	  },
180	  {
181	    applies: (policy) => policy.isFollowUpContract,
182	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
183	  },
184	];
185	
186	const policyModifiers = (policy: Policy, policyBase: number): number =>
187	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
188	    (total, clause) => total + policyBase * clause.rate,
189	    0,
190	  );
191	
192	const quote = (policy: Policy): QuoteResult => {
193	  const policyBase = policyBasePremium(policy.items);
194	  const modifiedPremium =
195	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
196	
197	  return {
198	    premium: roundPremiumInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
199	  };
200	};
201	
202	const insuranceSum = (items: Item[]): number =>
203	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
204	
205	// A policy issued by a quote step, tracked so later claims can draw on its cap.
206	type IssuedPolicy = {
207	  items: Item[];
208	  remainingCap: number;
209	};
210	
211	// The cap a fresh policy starts with: a multiple of the insured items' value,
212	// independent of any premium modifiers.
213	const issuePolicy = (items: Item[]): IssuedPolicy => ({
214	  items,
215	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
216	});
217	
218	// Item-scoped reimbursement clauses. Unlike the additive premium surcharges,
219	// these compete: the first applicable clause sets the rate outright, so list
220	// order is precedence. An item no clause applies to is reimbursed in full.
221	//
222	// The spec's dragon-material clause ("fully reimbursed") is deliberately not
223	// listed. Full reimbursement is already the default, and where it would
224	// collide with the high-enchantment clause the spec says the 50 % rule wins —
225	// which is what precedence gives. A dragon row would therefore be
226	// unreachable: no input distinguishes its presence from its absence.
227	const ITEM_REIMBURSEMENT_CLAUSES: {
228	  applies: (item: Item) => boolean;
229	  rate: number;
230	}[] = [
231	  {
232	    applies: (item) =>
233	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD,
234	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
235	  },
236	];
237	
238	const reimbursementRate = (item: Item): number =>
239	  ITEM_REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.rate ??
240	  FULL_REIMBURSEMENT_RATE;
241	
242	// Reimbursement clauses read the damaged item, so a claim resolves each
243	// damage entry back to the insured item it refers to.
244	const reimbursedAmount = (item: Item, amount: number): number =>
245	  amount * reimbursementRate(item);
246	
247	// A damage entry resolved to the one insured item it is settled against.
248	type DamagedItem = {
249	  item: Item;
250	  amount: number;
251	};
252	
253	// Each damage entry is settled against a *distinct* insured item, so a claim
254	// cannot draw on the same item twice. Pairing every entry up front — rather
255	// than resolving items one at a time while totalling — keeps the "each item is
256	// claimed at most once" rule in a single place, and leaves the payout
257	// arithmetic below free of the bookkeeping.
258	const pairDamagesWithInsuredItems = (
259	  damages: Damage[],
260	  items: Item[],
261	): DamagedItem[] => {
262	  const unclaimed = [...items];
263	
264	  return damages.map((damage) => {
265	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
266	    if (index === -1) {
267	      throw new Error(
268	        `the policy does not cover a further ${damage.itemType} to claim against`,
269	      );
270	    }
271	
272	    return { item: unclaimed.splice(index, 1)[0], amount: damage.amount };
273	  });
274	};
275	
276	// Each damaged item carries its own deductible, and a damage smaller than the
277	// deductible contributes nothing rather than clawing money back off the claim.
278	const payoutFor = ({ item, amount }: DamagedItem): number =>
279	  Math.max(0, reimbursedAmount(item, amount) - DEDUCTIBLE_PER_DAMAGE);
280	
281	// What the incident claims, before the policy's cap is applied.
282	const claimedAmount = (incident: Incident, items: Item[]): number =>
283	  pairDamagesWithInsuredItems(incident.damages, items).reduce(
284	    (total, damaged) => total + payoutFor(damaged),
285	    0,
286	  );
287	
288	// A claim draws its payout down from the policy's remaining cap, so the
289	// policy carries less cover into any later claim against it.
290	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
291	  ...policy,
292	  remainingCap: policy.remainingCap - payout,
293	});
294	
295	// A policy never pays out more cover than it has left.
296	const cappedBy = (amount: number, remainingCap: number): number =>
297	  Math.min(amount, remainingCap);
298	
299	// Settling a claim pays out what the incident claims, capped by the cover the
300	// policy has left and rounded down. Only this final figure is rounded, so the
301	// cap draws down by the amount actually paid. Returns the payout alongside the
302	// drawn-down policy, leaving it to the caller to record.
303	const settleClaim = (
304	  incident: Incident,
305	  policy: IssuedPolicy,
306	): { result: ClaimResult; policy: IssuedPolicy } => {
307	  const claimed = claimedAmount(incident, policy.items);
308	  const covered = cappedBy(claimed, policy.remainingCap);
309	  const payout = roundPayoutInMHPCOsFavour(covered);
310	  const settled = drawDownCap(policy, payout);
311	
312	  return {
313	    result: { payout, remainingCap: settled.remainingCap },
314	    policy: settled,
315	  };
316	};
317	
318	export const runScenario = (scenario: Scenario): ScenarioResult => {
319	  let hasIssuedContract = false;
320	  const policies = new Map<number, IssuedPolicy>();
321	
322	  const results = scenario.steps.map((step, index): StepResult => {
323	    if (step.op === "claim") {
324	      const { result, policy } = settleClaim(
325	        step.incident,
326	        policies.get(step.policy)!,
327	      );
328	      policies.set(step.policy, policy);
329	
330	      return result;
331	    }
332	
333	    policies.set(index, issuePolicy(step.items));
334	
335	    const result = quote({
336	      items: step.items,
337	      customer: scenario.customer,
338	      isFollowUpContract: hasIssuedContract,
339	    });
340	    hasIssuedContract = true;
341	
342	    return result;
343	  });
344	
345	  return { results };
346	};
